head(count_data)
head(plot_data)

## gllvm models
# Response only
my_model1 <- gllvm(
  y = count_data,
  num.lv = 2,
  family = "ZINB",
  sd.errors = FALSE
)

# Convergence
hist(my_model1$TMBfn$gr())

# Create ordination
my_colors <- c("red", "green", "yellow")
col_vect <- my_colors[plot_data$habClass]
ordiplot(my_model1, symbols = TRUE, biplot = TRUE,
         s.colors = col_vect, s.cex = 0.5, pch = 16)
legend(
  "topright",
  legend = levels(plot_data$habClass),
  col = my_colors,
  pch = 16,
  cex = 1
)

# Variance partitioning
plot(varPartitioning(my_model1))


# model 2: Categorical predictor and offset
my_model2 <- gllvm(
  y = count_data,
  X = plot_data,
  formula = ~habClass,
  offset = plot_data$offset_var,
  num.lv = 2,
  family = "ZINB",
  sd.errors = FALSE
)

# Convergence
hist(my_model2$TMBfn$gr())

# Create ordination
ordiplot(my_model2, symbols = TRUE, biplot = TRUE,
         s.colors = col_vect, s.cex = 0.5, pch = 16)
legend(
  "topright",
  legend = levels(plot_data$habClass),
  col = my_colors,
  pch = 16,
  cex = 1
)

# Variance partitioning
plot(varPartitioning(my_model2))
